  @doc ~S"""
  Revoke one user's grant to this app (grant_id from the users lookup): the approval is forgotten, so the next sign-in shows the consent screen again; the app's refresh tokens for the user stop working; a back-channel logout goes to the app (and its logout fan-out endpoints) for each live sign-in, and the app's webhook gets grant.revoked. The person's Atlas account and other apps are untouched. Also accepts an instance secret key (`secretKey`) with `atlas_id_grants:write` (or the `privacy:grants:revoke` / `privacy:execute` presets), for the apps that instance manages or has adopted (PUT …/managed_by); any other app is 404 to it.

  `DELETE /v1/platform/atlas_id_apps/{id}/grants/{grantId}`. Required scope: `platform:atlas_id_apps:write`.

  Response fields: `object`, `id`, `sub`, `revoked`, `tokens_revoked`, `backchannel_logouts`.
  """
  def delete_grants(client, id, grant_id, opts \\ []),
    do: Atlas.Client.request(client, :delete, "/v1/platform/atlas_id_apps/{id}/grants/{grantId}", %{"id" => id, "grantId" => grant_id}, nil, opts)

  @doc ~S"""
